import React from 'react';
import { Folder, FileCode, CheckCircle2 } from 'lucide-react';

interface FolderCardProps {
  item: {
    name: string;
    path: string;
    type: 'folder' | 'file';
    role: string;
  };
  isSelected: boolean;
  onSelect: () => void;
}

export function FolderCard({ item, isSelected, onSelect }: FolderCardProps) {
  const Icon = item.type === 'folder' ? Folder : FileCode;
  return (
    <div
      onClick={onSelect}
      className={`cursor-pointer p-4 rounded-xl border transition-all flex items-start gap-3 ${
        isSelected
          ? 'border-emerald-500 bg-emerald-500/10 shadow-sm'
          : 'border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-slate-300'
      }`}
    >
      <div
        className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${
          isSelected
            ? 'bg-emerald-500 text-white'
            : 'bg-slate-100 dark:bg-slate-800 text-slate-500'
        }`}
      >
        <Icon className="w-5 h-5" />
      </div>
      <div className="min-w-0 flex-1">
        <div className="font-bold text-sm text-slate-800 dark:text-slate-100 flex items-center justify-between">
          <span className="truncate">{item.name}</span>
          {isSelected && <CheckCircle2 className="w-4 h-4 text-emerald-500" />}
        </div>
        <div className="text-[11px] font-mono text-slate-400 truncate">{item.path}</div>
        <div className="text-xs text-slate-500 mt-1 font-medium">{item.role}</div>
      </div>
    </div>
  );
}

